// Report data: collects everything the report needs. All numbers are computed here, not by the AI.
const RUN = $('Report run1').first().json.run_id;
const f = o => (o && o.fields) ? { id: o.id, ...o.fields } : o;
const sel = v => String(v && v.name ? v.name : (v === null || v === undefined ? '' : v)).toLowerCase();
const num = v => (v === null || v === undefined || v === '') ? null : Number(v);

// Profile
const pf = f($('Report profile1').first().json);
let raw = {};
try { raw = JSON.parse(pf.profile_json || '{}'); } catch (e) {}
const pv = k => { const v = raw[k] && raw[k].value; if (v === null || v === undefined || v === '') return null; return Array.isArray(v) ? v.map(i => (i && typeof i === 'object') ? i.item : i).join('; ') : String(v); };
const company = {
  name: pv('company_name') || pf.company_name || pf.domain,
  domain: pf.domain,
  one_liner: pv('one_liner'),
  category: pv('category'),
  hq: pv('hq_city'),
  buyers: pv('buyer_industries'),
  offering: pv('offering'),
};
const focusMarket = String(pf.focus_market && pf.focus_market.name ? pf.focus_market.name : (pf.focus_market || '')) || 'Global';
const marketOn = focusMarket !== 'Global';
// checkbox: empty means yes (show global players as their own section)
const includeGlobal = pf.include_global === undefined || pf.include_global === null || pf.include_global === '' ? true : pf.include_global === true;

// Competitors: approved only; if nobody is approved yet, draft mode with all non-rejected
const all = $('Report competitors1').all().map(i => f(i.json)).filter(c => sel(c.status) !== 'rejected');
const approved = all.filter(c => c.approved === true);
const draft = approved.length === 0;
const comps = (draft ? all : approved).filter(c => num(c.rank) !== null).sort((a, b) => num(a.rank) - num(b.rank));

const parseEvidence = t => String(t || '').split('\n').map(l => {
  const m = l.match(/^\[(\w+)\]\s*"(.+)"\s*-\s*(https?:\S+)\s*$/);
  return m ? { force: m[1], quote: m[2], url: m[3] } : null;
}).filter(Boolean);

const rows = comps.map(c => ({
  id: c.id, rank: num(c.rank), name: c.name, domain: c.domain || null,
  website: c.website_url || (c.domain ? 'https://' + c.domain : null),
  linkedin: c.linkedin_url || null,
  score: num(c.score), tier: sel(c.tier) ? (c.tier.name || c.tier) : '',
  breakdown: c.score_breakdown || '',
  status: sel(c.status),
  forces: c.forces_text || '',
  verdicts: { rivalry: sel(c.verdict_rivalry), substitute: sel(c.verdict_substitute), new_entrant: sel(c.verdict_new_entrant) },
  what: c.what_they_do || '',
  judge: c.judge_reasons || '',
  employees: num(c.employees), country: c.hq_country || null, city: c.hq_city || null,
  founded: num(c.founded_year), funding: c.funding_total || null, funding_usd: num(c.funding_total_usd),
  last_funding_date: c.last_funding_date || null, last_funding_stage: c.last_funding_stage || null,
  growth_12m: num(c.headcount_growth_12m), parent: c.parent_company || null,
  platform_owner: c.platform_owner === true,
  job_focus: sel(c.job_focus) || 'unknown',
  business_type: sel(c.business_type) || '',
  market: sel(c.market_presence) || 'unknown',
  market_note: c.market_note || '',
  // global = clear data, but no presence in the focus market found
  global: marketOn && sel(c.market_presence) === 'none',
  evidence: parseEvidence(c.evidence_text).slice(0, 3),
  approved: c.approved === true,
}));

// Forces (F4, F5)
const forces = {};
for (const it of $('Report forces1').all()) {
  const x = f(it.json);
  let drivers = [];
  try { drivers = JSON.parse(x.drivers_json || '[]'); } catch (e) {}
  forces[sel(x.force)] = { overall: sel(x.overall), summary: x.summary || '', drivers };
}
const buyer = forces.buyer_power || { overall: 'unknown', drivers: [] };
const supplier = forces.supplier_power || { overall: 'unknown', drivers: [] };

// Same weight rules as Score + rank (so the method box matches the scores)
const W = { rivalry: 1.0, substitute: 0.8, new_entrant: 0.6 };
if (buyer.overall === 'high') { W.rivalry += 0.1; W.substitute += 0.2; }
if (buyer.overall === 'medium') { W.substitute += 0.1; }
if ((buyer.drivers.find(d => d.driver === 'switching_cost') || {}).rating === 'high') W.new_entrant += 0.2;
const platform_mult = supplier.overall === 'high' || supplier.overall === 'medium' ? 1.1 : 1.0;

// Summary numbers
const inMarket = rows.filter(r => !r.global);
const globalRows = rows.filter(r => r.global);
// number each list on its own: DACH list 1..n, global list 1..m (overall rank kept for reference)
inMarket.forEach((r, i) => { r.overall_rank = r.rank; r.rank = i + 1; });
globalRows.forEach((r, i) => { r.overall_rank = r.rank; r.rank = i + 1; });
const tierOf = t => inMarket.filter(r => r.tier === t);
const monthsAgo = d => d ? (Date.now() - new Date(d).getTime()) / (30.44 * 864e5) : Infinity;
const counts = {
  analysed: rows.length,
  in_market: inMarket.length,
  global: globalRows.length,
  primary: tierOf('Primary threat').length,
  watch: tierOf('Watch').length,
  peripheral: tierOf('Peripheral').length,
  rivals: rows.filter(r => r.verdicts.rivalry === 'true').length,
  substitutes: rows.filter(r => r.verdicts.substitute === 'true').length,
  new_entrants: rows.filter(r => r.verdicts.new_entrant === 'true').length,
  platform_owners: rows.filter(r => r.platform_owner).length,
  funded_24m: rows.filter(r => monthsAgo(r.last_funding_date) <= 24).length,
};

// Facts for the AI: the only material it may use
const fmt = r => [
  `${r.name} (rank ${r.rank}, score ${r.score}, ${r.tier})`,
  `found as: ${r.forces}; judge: ${r.judge.replace(/\n/g, ' | ')}`,
  `what they do: ${r.what}`,
  `size: ${r.employees ?? 'unknown'} employees; HQ: ${[r.city, r.country].filter(Boolean).join(', ') || 'unknown'}; founded: ${r.founded ?? 'unknown'}`,
  `market presence in ${focusMarket}: ${r.market} (${r.market_note}); job focus: ${r.job_focus.replace('_', ' ')}`,
  `funding: ${r.funding || 'unknown'}${r.last_funding_stage ? ', last round ' + r.last_funding_stage : ''}${r.last_funding_date ? ' on ' + String(r.last_funding_date).slice(0, 10) : ''}; headcount growth 12m: ${r.growth_12m === null ? 'unknown' : Math.round(r.growth_12m * 100) + '%'}`,
  r.parent ? `parent company: ${r.parent}` : null,
  r.platform_owner ? 'platform owner (TMS/ERP/visibility platform with its own audit or spend module)' : null,
].filter(Boolean).join('\n');

const facts_text = [
  `ANALYSED COMPANY: ${company.name} (${company.domain}). ${company.one_liner || ''} Category: ${company.category || 'unknown'}. HQ: ${company.hq || 'unknown'}. Buyers: ${company.buyers || 'unknown'}.`,
  '',
  `FOCUS MARKET: ${focusMarket}. ${marketOn ? counts.in_market + ' competitors are present in this market or have no clear location data; ' + counts.global + ' are global players without a presence found in ' + focusMarket + '.' : 'No market focus.'}`,
  '',
  `COUNTS: ${counts.analysed} competitors in this report: ${counts.primary} primary threats, ${counts.watch} watch, ${counts.peripheral} peripheral. ${counts.rivals} direct rivals, ${counts.substitutes} substitutes, ${counts.new_entrants} new entrants. ${counts.platform_owners} platform owners. ${counts.funded_24m} raised money in the last 24 months.`,
  '',
  `BUYER POWER: ${buyer.overall}. ` + buyer.drivers.map(d => `${d.driver}: ${d.rating} (${d.reason})`).join(' '),
  `SUPPLIER POWER: ${supplier.overall}. ` + supplier.drivers.map(d => `${d.driver}: ${d.rating} (${d.reason})`).join(' '),
  '',
  'PRIMARY THREATS:',
  ...tierOf('Primary threat').map(fmt),
  '',
  'WATCH LIST:',
  ...tierOf('Watch').map(r => `${r.name} (rank ${r.rank}, score ${r.score}): ${r.what}`),
  '',
  `GLOBAL PLAYERS WITHOUT A PRESENCE FOUND IN ${focusMarket.toUpperCase()}:`,
  ...(globalRows.length ? globalRows.map(r => `${r.name} (rank ${r.rank}, score ${r.score}, HQ ${r.country || 'unknown'}): ${r.what}`) : ['none']),
].join('\n');

return [{ json: {
  run_id: RUN, draft, generated_at: new Date().toISOString().slice(0, 10),
  company, counts, rows, buyer, supplier, focus_market: focusMarket, market_on: marketOn, include_global: includeGlobal,
  weights: { rivalry: +W.rivalry.toFixed(2), substitute: +W.substitute.toFixed(2), new_entrant: +W.new_entrant.toFixed(2), platform_mult },
  primary_names: tierOf('Primary threat').map(r => r.name),
  facts_text,
} }];

// Style requests: finds the company lines in the filled Doc and makes them bold and bigger
const doc = $input.first().json;
const requests = [];
const style = (start, end, size) => {
  if (end <= start) return;
  requests.push({ updateTextStyle: {
    range: { startIndex: start, endIndex: end },
    textStyle: { bold: true, fontSize: { magnitude: size, unit: 'PT' } },
    fields: 'bold,fontSize',
  } });
};
const boldOnly = (start, end) => {
  if (end <= start) return;
  requests.push({ updateTextStyle: { range: { startIndex: start, endIndex: end }, textStyle: { bold: true }, fields: 'bold' } });
};

const LABELS = ['What they do:', 'Why it matters:', 'Market (', 'Evidence:', 'Score breakdown:'];
for (const block of (doc.body && doc.body.content) || []) {
  const p = block.paragraph;
  if (!p || !p.elements || !p.elements.length) continue;
  const start = p.elements[0].startIndex;
  const text = p.elements.map(e => (e.textRun && e.textRun.content) || '').join('');
  const t = text.replace(/\n$/, '');

  // Primary threat header: "1.  GoComet  —  score 95.7" -> whole line bold, 14 pt
  if (/^\d+\.\s+.+\s—\s+score\s+[\d.]+\s*$/.test(t)) { style(start, start + t.length, 14); continue; }

  // Watch / peripheral line: "6.  FreightFox  ·  66.9  ·  ..." -> rank + name bold, 11.5 pt
  const m = t.match(/^(\d+\.\s+.+?)\s+·/);
  if (m) { style(start, start + m[1].length, 11.5); continue; }

  // Labels inside the threat blocks
  const label = LABELS.find(l => t.startsWith(l));
  if (label) boldOnly(start, start + label.length);
}

return [{ json: { documentId: doc.documentId, requests, styled: requests.length } }];

// Doc blocks: checks the AI text against the facts, then builds one plain-text block per template placeholder
const d = $('Report data1').first().json;
const out = $input.first().json;

// 1. Parse AI JSON (with repair). If it still fails, the report is built without AI text instead of crashing.
const rawAi = String(out.output || out.text || '').replace(/```json|```/g, '').trim();
const a = rawAi.indexOf('{'), b = rawAi.lastIndexOf('}');
let txt = a >= 0 && b > a ? rawAi.slice(a, b + 1) : '';
// remove line breaks the model stream put inside strings (they split words like "Wat\nch")
const fixStrings = t => {
  let res = '', inStr = false, esc = false;
  for (const ch of t) {
    if (inStr) {
      if (esc) { res += ch; esc = false; continue; }
      if (ch === '\\') { res += ch; esc = true; continue; }
      if (ch === '"') { inStr = false; res += ch; continue; }
      if (ch === '\n') { continue; }
      if (ch === '\r') { continue; }
      if (ch === '\t') { res += ' '; continue; }
      res += ch;
    } else {
      if (ch === '"') inStr = true;
      res += ch;
    }
  }
  return res;
};
let ai = null;
const attempts = [
  t => t,
  t => t.replace(/,\s*([}\]])/g, '$1'),
  t => fixStrings(t),
  t => fixStrings(t).replace(/,\s*([}\]])/g, '$1'),
  t => fixStrings(t.replace(/[“”]/g, '"')).replace(/,\s*([}\]])/g, '$1'),
];
for (const fn of attempts) { try { ai = JSON.parse(fn(txt)); break; } catch (e) {} }
const aiFailed = !ai;
if (aiFailed) ai = { executive_summary: '', threats: [], market_position: '', implications: [] };

// 2. Number check: every number in the AI text must appear in the facts, else the sentence is removed
const factsNorm = String(d.facts_text).replace(/,/g, '');
const removed = [];
const clean = t => String(t || '').replace(/[\r\n]+/g, '').replace(/[ \t]{2,}/g, ' ').trim();
const checkText = t => clean(t).split(/(?<=[.!?])\s+/).filter(s => {
  const nums = (s.replace(/,/g, '').match(/\d+(\.\d+)?/g) || []);
  const bad = nums.filter(n => !factsNorm.includes(n));
  if (bad.length) { removed.push(s + ' [not in data: ' + bad.join(', ') + ']'); return false; }
  return true;
}).join(' ');
const execSummary = checkText(ai.executive_summary);
const marketText = checkText(ai.market_position);
const whyBy = {};
for (const t of ai.threats || []) if (d.primary_names.includes(t.name)) whyBy[t.name] = checkText(t.why);
const implications = (ai.implications || []).map(checkText).filter(Boolean);

// 3. Text helpers
const host = u => { const m = String(u || '').match(/^https?:\/\/(?:www\.)?([^\/]+)/); return m ? m[1] : (u || ''); };
const pct = g => g === null || g === undefined ? '–' : (g > 0 ? '+' : '') + Math.round(g * 100) + '%';
const n = v => v === null || v === undefined || v === '' || Number(v) === 0 ? '–' : Number(v).toLocaleString('en-US');
const up = s => String(s || 'unknown').toUpperCase();
const forceList = r => ['rivalry', 'substitute', 'new_entrant'].filter(k => r.verdicts[k] === 'true' || r.verdicts[k] === 'unsure')
  .map(k => k.replace('_', ' ') + (r.verdicts[k] === 'unsure' ? ' (unsure)' : '')).join(', ');
const inMarket = d.rows.filter(r => !r.global);
const globalRows = d.rows.filter(r => r.global);
const tier = t => inMarket.filter(r => r.tier === t);
const FOCUS_LABEL = { core: 'core business', major_module: 'major module', minor_feature: 'side feature', unknown: 'unknown' };
const MARKET_LABEL = { local: 'local', active: 'active in market', none: 'no presence found', unknown: 'location unknown', 'n/a': '–' };
const marketLine = r => 'Market (' + d.focus_market + '): ' + (MARKET_LABEL[r.market] || r.market) + (r.market_note ? ' – ' + r.market_note : '') +
  '  ·  Focus: ' + (FOCUS_LABEL[r.job_focus] || r.job_focus);
const c = d.counts;

const drivers = f => (f.drivers || []).map(x => '• ' + x.driver.replace(/_/g, ' ') + ' — ' + up(x.rating) + ': ' + x.reason +
  ' (' + (x.source === 'our data' ? 'our data' : host(x.source)) + ')').join('\n') || 'No drivers rated.';

const threat = r => [
  r.rank + '.  ' + r.name + '  —  score ' + r.score,
  [r.website ? host(r.website) : null, forceList(r), r.platform_owner ? 'platform owner' : null].filter(Boolean).join('  ·  '),
  'What they do: ' + (r.what || '–'),
  marketLine(r),
  whyBy[r.name] ? 'Why it matters: ' + whyBy[r.name] : null,
  'Employees ' + n(r.employees) + '  ·  HQ ' + ([r.city, r.country].filter(Boolean).join(', ') || '–') + '  ·  Founded ' + (r.founded || '–') +
    '  ·  Funding ' + (r.funding || '–') + (r.last_funding_date ? '  ·  Last round ' + [r.last_funding_stage, String(r.last_funding_date).slice(0, 10)].filter(Boolean).join(', ') : '') +
    '  ·  Headcount 12m ' + pct(r.growth_12m) + (r.parent ? '  ·  Parent ' + r.parent : ''),
  r.evidence.length ? 'Evidence:\n' + r.evidence.map(e => '   • “' + e.quote + '” — ' + e.force.replace('_', ' ') + ', ' + e.url).join('\n') : null,
  'Score breakdown: ' + r.breakdown,
].filter(Boolean).join('\n');

const line = r => r.rank + '.  ' + r.name + '  ·  ' + r.score + '  ·  ' + (forceList(r) || '–') + '  ·  ' + (r.what || '–') +
  '  ·  ' + n(r.employees) + ' employees' + (r.funding ? '  ·  ' + r.funding : '') +
  '  ·  ' + (FOCUS_LABEL[r.job_focus] || r.job_focus) + (d.market_on ? '  ·  ' + (MARKET_LABEL[r.market] || r.market) : '');

// global players: data shows no presence in the focus market (yet)
const globalLine = r => r.rank + '.  ' + r.name + '  ·  ' + r.score + '  ·  ' + (forceList(r) || '–') + '  ·  ' + (r.what || '–') +
  '  ·  HQ ' + ([r.city, r.country].filter(Boolean).join(', ') || '–') + '  ·  ' + n(r.employees) + ' employees';
const globalBlock = !d.market_on ? 'No focus market was set, so all competitors are listed above.'
  : !d.include_global ? globalRows.length + ' global players without a presence found in ' + d.focus_market + ' were left out at the client\'s request.'
  : globalRows.length ? 'Companies with relevant products whose data shows no presence in ' + d.focus_market + ' yet. Scores include a 0.8 discount. Watch them for market entry.\n' + globalRows.map(globalLine).join('\n')
  : 'None.';

const citations = [...new Set([...(d.buyer.drivers || []), ...(d.supplier.drivers || [])].map(x => x.source).filter(s => s && s !== 'our data'))];

const method = [
  'Pipeline: company website → verified profile (every field backed by a quote) → Porter search for rivals, substitutes and new entrants in English and the focus market\'s language (Perplexity, quotes checked in code) → Apollo enrichment → AI judge per company with company data and evidence (quotes checked in code) → buyer and supplier power research → scoring in code → human approval.',
  'Score = 100 × confidence × (0.6 × relevance + 0.2 × size + 0.2 × momentum) × platform multiplier × market factor. Relevance and momentum are weighted by how central the job is to the competitor (core business 1.0, major module 0.8, side feature 0.5). Unknown size is left out, not counted as small.',
  'Force weights: rivalry ' + d.weights.rivalry + ', substitute ' + d.weights.substitute + ', new entrant ' + d.weights.new_entrant + ' (adjusted by buyer power). Platform owners × ' + d.weights.platform_mult + ' (supplier power). Confidence: verified 1.0, unsure 0.7.',
  d.market_on ? 'Market (' + d.focus_market + '): local = HQ in the market; active = HQ elsewhere, but a market domain, a market version of the own website (hreflang tag, /de/ pages, de. subdomain or .de domain, checked in code) or own website pages in the market language; no presence found = known HQ elsewhere and no market signal (score × 0.8); location unknown = no company data, no discount. A missing signal does not prove absence.' : null,
  'Tiers: 70+ primary threat, 50–69 watch, below 50 peripheral. Breakdown codes: R relevance, S size, M momentum, C confidence.',
  'Not assessed in this version: customer segment (company size of the competitor\'s customers).',
  aiFailed ? 'Quality check: the AI text could not be read, so the written parts were left out.' : null,
  removed.length ? 'Quality check: ' + removed.length + ' AI sentence(s) removed because they contained numbers not found in the data.' : null,
].filter(Boolean).join('\n');

// Google Docs rejects empty replace text, so every block gets a fallback
const nz = (s, fb) => (s && String(s).trim()) ? String(s) : (fb || '–');

return [{ json: {
  run_id: d.run_id, draft: d.draft, ai_failed: aiFailed, ai_raw: rawAi.slice(0, 4000), removed_sentences: removed,
  doc_title: 'Competitor report – ' + d.company.name + ' – ' + d.generated_at,
  file_name: 'competitor-report-' + String(d.company.domain || 'company').replace(/[^a-z0-9.-]/gi, '') + '-' + d.generated_at + '.pdf',
  company_name: nz(d.company.name),
  domain: nz(d.company.domain),
  category: nz(d.company.category),
  date: d.generated_at,
  draft_note: d.draft ? 'Automated analysis. The competitor list has not yet been reviewed by hand.' : ' ',
  executive_summary: nz(execSummary, 'Not available.'),
  count_analysed: String(c.analysed), count_primary: String(c.primary), count_watch: String(c.watch),
  count_peripheral: String(c.peripheral), count_platform: String(c.platform_owners), count_funded: String(c.funded_24m),
  implications: nz(implications.map(i => '• ' + i).join('\n'), 'Not available.'),
  market_position: nz(marketText, ' '),
  buyer_overall: up(d.buyer.overall), buyer_drivers: drivers(d.buyer),
  supplier_overall: up(d.supplier.overall), supplier_drivers: drivers(d.supplier),
  primary_threats: nz(tier('Primary threat').map(threat).join('\n\n'), 'No primary threats.'),
  watch_list: nz(tier('Watch').map(line).join('\n'), 'None.'),
  peripheral_list: nz(tier('Peripheral').map(line).join('\n'), 'None.'),
  method,
  sources: nz(citations.map(u => '• ' + u).join('\n'), 'None.'),
  global_players: nz(globalBlock, 'None.'),
} }];
